import "server-only";
import { getV3AuthorizationActor } from "@/app/api/v3/lib/auth";
import { requireUnifyFeedbackWorkspaceAccess } from "@/app/api/v3/lib/feedback-access";
import { problemForbidden, problemUnauthorized } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import type { V3WorkspaceContext } from "@/app/api/v3/lib/workspace-context";
import { can } from "@/lib/authorization";
import { getFeedbackDirectoryAssignmentAuthorizationAction } from "@/lib/authorization/permission-action";
import type { TTeamPermission } from "@/modules/ee/teams/workspace-teams/types/team";

/**
 * Authorize a Unify Feedback taxonomy request against a workspace + feedback directory.
 *
 * Reproduces the exact guard the legacy server actions applied (`ensureAccess` + `ensureDirectoryAccess`):
 * the shared `requireUnifyFeedbackWorkspaceAccess` covers workspace permission plus the
 * `feedbackDirectories` entitlement, and this wrapper adds the directory-belongs-to-workspace membership
 * check. Omitting either would widen access beyond today.
 *
 * Returns a `Response` (401/403) to short-circuit on failure, or the resolved workspace context on success.
 */
export async function requireUnifyDirectoryAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  directoryId: string,
  minPermission: TTeamPermission,
  requestId: string,
  instance?: string
): Promise<Response | V3WorkspaceContext> {
  const context = await requireUnifyFeedbackWorkspaceAccess(
    authentication,
    workspaceId,
    minPermission,
    requestId,
    instance
  );
  if (context instanceof Response) {
    return context;
  }

  const actor = getV3AuthorizationActor(authentication);
  if (!actor) {
    return problemUnauthorized(requestId, "Not authenticated", instance);
  }

  const allowed = await can(actor, getFeedbackDirectoryAssignmentAuthorizationAction(minPermission), {
    type: "feedbackDirectoryAssignment",
    feedbackDirectoryId: directoryId,
    workspaceId: context.workspaceId,
  });
  if (!allowed) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  return context;
}

/**
 * Authorize a request that *changes* directory-level taxonomy state (start a run, rename or remove a
 * node) — organization owners and managers only (ENG-1770).
 *
 * A feedback directory is shared by every workspace it is assigned to, and it has one taxonomy tree:
 * a workspace `readWrite` member would otherwise rewrite or delete topics that other workspaces read.
 * Since taxonomy state carries no workspace, workspace permissions cannot draw that line, so changing
 * it stays with the roles that own org-level data.
 *
 * Workspace access is still required on top of the org role, so the directory-belongs-to-workspace
 * check still applies and an owner cannot reach a directory through an unrelated workspace.
 */
export async function requireUnifyDirectoryMutationAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  directoryId: string,
  requestId: string,
  instance?: string
): Promise<Response | V3WorkspaceContext> {
  const context = await requireUnifyDirectoryAccess(
    authentication,
    workspaceId,
    directoryId,
    "read",
    requestId,
    instance
  );
  if (context instanceof Response) {
    return context;
  }

  const userId = getSessionUserId(authentication);
  if (!userId) {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  const allowed = await can({ type: "user", id: userId }, "organization.manage", {
    type: "organization",
    id: context.organizationId,
  });
  if (!allowed) {
    return problemForbidden(
      requestId,
      "Only organization owners and managers can change a feedback directory's taxonomy",
      instance
    );
  }

  return context;
}

/** Extract the session user id (used as Hub `actor_id`). Present because these routes are session-auth. */
export function getSessionUserId(authentication: TV3Authentication): string | null {
  if (authentication && "user" in authentication && authentication.user?.id) {
    return authentication.user.id;
  }
  return null;
}

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { assertCan } from "@/lib/authorization";
import { capturePostHogEvent } from "@/lib/posthog";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import {
  createApiKey,
  deleteApiKey,
  rotateApiKey,
  updateApiKey,
} from "@/modules/organization/settings/api-keys/lib/api-key";
import { assertCanGrantOrganizationAccess } from "@/modules/organization/settings/api-keys/lib/organization-access";
import { ZApiKeyCreateInput, ZApiKeyUpdateInput } from "./types/api-keys";

const ZDeleteApiKeyAction = z.object({
  id: ZId,
});

export const deleteApiKeyAction = authenticatedActionClient.inputSchema(ZDeleteApiKeyAction).action(
  withAuditLogging("deleted", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.id);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.id,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.id;

    const result = await deleteApiKey(parsedInput.id);
    ctx.auditLoggingCtx.oldObject = result;
    return result;
  })
);

const ZCreateApiKeyAction = z.object({
  organizationId: ZId,
  apiKeyData: ZApiKeyCreateInput,
});

export const createApiKeyAction = authenticatedActionClient.inputSchema(ZCreateApiKeyAction).action(
  withAuditLogging("created", "apiKey", async ({ ctx, parsedInput }) => {
    await assertCan({ type: "user", id: ctx.user.id }, "organization.manage_api_keys", {
      type: "organization",
      id: parsedInput.organizationId,
    });

    // Managing API keys and managing organization users are two different capabilities, and a key
    // carrying `accessControl.write` grants the second. Gate it on the org's user-management floor so
    // an install that restricts user management to owners cannot have that restriction minted away.
    await assertCanGrantOrganizationAccess(
      ctx.user.id,
      parsedInput.organizationId,
      parsedInput.apiKeyData.organizationAccess
    );

    ctx.auditLoggingCtx.organizationId = parsedInput.organizationId;

    const result = await createApiKey(parsedInput.organizationId, ctx.user.id, parsedInput.apiKeyData);
    ctx.auditLoggingCtx.newObject = parsedInput.apiKeyData;
    ctx.auditLoggingCtx.apiKeyId = result.id;
    capturePostHogEvent(
      ctx.user.id,
      "api_key_created",
      { api_key_id: result.id },
      { organizationId: parsedInput.organizationId }
    );
    return result;
  })
);

const ZRotateApiKeyAction = z.object({
  apiKeyId: ZId,
});

const ZUpdateApiKeyAction = z.object({
  apiKeyId: ZId,
  apiKeyData: ZApiKeyUpdateInput,
});

export const rotateApiKeyAction = authenticatedActionClient.inputSchema(ZRotateApiKeyAction).action(
  withAuditLogging("rotated", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.apiKeyId);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.apiKeyId,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.apiKeyId;
    const result = await rotateApiKey(parsedInput.apiKeyId, ctx.user.id);
    ctx.auditLoggingCtx.newObject = { actualKey: result.actualKey };
    return result;
  })
);

export const updateApiKeyAction = authenticatedActionClient.inputSchema(ZUpdateApiKeyAction).action(
  withAuditLogging("updated", "apiKey", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromApiKeyId(parsedInput.apiKeyId);
    await assertCan({ type: "user", id: ctx.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: parsedInput.apiKeyId,
    });

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.apiKeyId = parsedInput.apiKeyId;
    ctx.auditLoggingCtx.newObject = parsedInput.apiKeyData;
    return await updateApiKey(parsedInput.apiKeyId, parsedInput.apiKeyData);
  })
);

import { z } from "zod";
